+setup:
+  - do:
+      indices.create:
+          index: test
+          body:
+            settings:
+              number_of_shards: 1
+            mappings:
+              properties:
+                tags:
+                  type: text
+                number:
+                  type: integer
+
+  - do:
+      bulk:
+        index: test
+        refresh: true
+        body:
+          - '{"index": {}}'
+          - '{"tags": "kibana", "number": 1}'
+          - '{"index": {}}'
+          - '{"tags": "kibana", "number": 2}'
+          - '{"index": {}}'
+          - '{"tags": "kibana", "number": 3}'
+          - '{"index": {}}'
+          - '{"tags": "javascript", "number": 4}'
+
+---
+small shard_size:
+  - do:
+      search:
+        body:
+          query:
+            query_string:
+              query: 'tags:kibana OR tags:javascript'
+          aggs:
+            sample:
+              sampler:
+                shard_size: 1
+              aggs:
+                min_number:
+                  min:
+                    field: number
+                max_number:
+                  max:
+                    field: number
+
+
+  - match: { hits.total.value: 4 }
+  - match: { aggregations.sample.doc_count: 1 }
+  # The document with 4 has the highest score so we pick that one.
